const EffectDefinition* EffectCatalog::find(const std::string& id) const {
  const auto found = index.find(id);
  if (found != index.end()) return &definitions[found->second];
  for (std::size_t i = 0; i < definitions.size(); ++i) {
    if (definitions[i].id == id) { index.emplace(id, i); return &definitions[i]; }
  }
  return nullptr;
}

